    CHANGED_FILES: '.changeset/major-update.md',
  };

  const readFile = mock.fn(async path => {
    if (path.endsWith('pre.json')) {
      return '{"mode":"pre","tag":"beta"}';
    }

    return `---\n@ai-sdk/provider: major\n---\n## Test changeset`;
