import { describe, expect, it } from 'vitest';
import { resolveDeepAgentsEnv } from './deepagents-auth';

describe('resolveDeepAgentsEnv', () => {
  it('pins explicit anthropic auth', () => {
    const env = resolveDeepAgentsEnv({
      auth: {
        anthropic: { apiKey: 'sk-ant', baseUrl: 'https://example.test' },
      },
      processEnv: {},
    });
    expect(env).toEqual({
      ANTHROPIC_API_KEY: 'sk-ant',
      ANTHROPIC_BASE_URL: 'https://example.test',
    });
  });

  it('passes through an anthropic auth token', () => {
    const env = resolveDeepAgentsEnv({
      auth: { anthropic: { authToken: 'tok' } },
      processEnv: {},
    });
    expect(env).toEqual({ ANTHROPIC_AUTH_TOKEN: 'tok' });
  });

  it('routes through the gateway anthropic endpoint (no /v1 suffix)', () => {
    const env = resolveDeepAgentsEnv({
      auth: { gateway: { apiKey: 'gw-key' } },
      processEnv: {},
    });
    expect(env.AI_GATEWAY_API_KEY).toBe('gw-key');
    expect(env.ANTHROPIC_API_KEY).toBe('gw-key');
    expect(env.ANTHROPIC_BASE_URL).toBe('https://ai-gateway.vercel.sh');
  });

  it('trims a trailing slash from a custom gateway base url', () => {
    const env = resolveDeepAgentsEnv({
      auth: { gateway: { apiKey: 'gw-key', baseUrl: 'https://gw.test/' } },
      processEnv: {},
    });
    expect(env.ANTHROPIC_BASE_URL).toBe('https://gw.test');
  });

  it('prefers explicit anthropic auth over ambient gateway creds', () => {
    const env = resolveDeepAgentsEnv({
      auth: { anthropic: { apiKey: 'sk-ant' } },
      processEnv: { AI_GATEWAY_API_KEY: 'ambient-gw' },
    });
    expect(env).toEqual({ ANTHROPIC_API_KEY: 'sk-ant' });
  });

  it('falls back to ambient gateway env before ambient anthropic creds', () => {
    const env = resolveDeepAgentsEnv({
      processEnv: {
        AI_GATEWAY_API_KEY: 'ambient-gw',
        ANTHROPIC_API_KEY: 'ambient-ant',
      },
    });
    expect(env.AI_GATEWAY_API_KEY).toBe('ambient-gw');
    expect(env.ANTHROPIC_API_KEY).toBe('ambient-gw');
    expect(env.ANTHROPIC_BASE_URL).toBe('https://ai-gateway.vercel.sh');
  });

  it('falls back to ambient OIDC token as the gateway key', () => {
    const env = resolveDeepAgentsEnv({
      processEnv: { VERCEL_OIDC_TOKEN: 'oidc-token' },
    });
    expect(env.AI_GATEWAY_API_KEY).toBe('oidc-token');
  });

  it('falls back to ambient anthropic when no gateway creds exist', () => {
    const env = resolveDeepAgentsEnv({
      processEnv: { ANTHROPIC_API_KEY: 'ambient-ant' },
    });
    expect(env).toEqual({ ANTHROPIC_API_KEY: 'ambient-ant' });
  });
});

import { resourceUrlFromServerUrl, checkResourceAllowed } from './oauth-util';
import { describe, it, expect } from 'vitest';

describe('auth-utils', () => {
  describe('resourceUrlFromServerUrl', () => {
    it('should remove fragments', () => {
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com/path#fragment'))
          .href,
      ).toBe('https://example.com/path');
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com#fragment')).href,
      ).toBe('https://example.com/');
      expect(
        resourceUrlFromServerUrl(
          new URL('https://example.com/path?query=1#fragment'),
        ).href,
      ).toBe('https://example.com/path?query=1');
    });

    it('should return URL unchanged if no fragment', () => {
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com')).href,
      ).toBe('https://example.com/');
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com/path')).href,
      ).toBe('https://example.com/path');
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com/path?query=1'))
          .href,
      ).toBe('https://example.com/path?query=1');
    });

    it('should keep everything else unchanged', () => {
      // Case sensitivity preserved
      expect(
        resourceUrlFromServerUrl(new URL('https://EXAMPLE.COM/PATH')).href,
      ).toBe('https://example.com/PATH');
      // Ports preserved
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com:443/path')).href,
      ).toBe('https://example.com/path');
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com:8080/path')).href,
      ).toBe('https://example.com:8080/path');
      // Query parameters preserved
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com?foo=bar&baz=qux'))
          .href,
      ).toBe('https://example.com/?foo=bar&baz=qux');
      // Trailing slashes preserved
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com/')).href,
      ).toBe('https://example.com/');
      expect(
        resourceUrlFromServerUrl(new URL('https://example.com/path/')).href,
      ).toBe('https://example.com/path/');
    });
  });

  describe('resourceMatches', () => {
    it('should match identical URLs', () => {
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/path',
          configuredResource: 'https://example.com/path',
        }),
      ).toBe(true);
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/',
          configuredResource: 'https://example.com/',
        }),
      ).toBe(true);
    });

    it('should not match URLs with different paths', () => {
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/path1',
          configuredResource: 'https://example.com/path2',
        }),
      ).toBe(false);
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/',
          configuredResource: 'https://example.com/path',
        }),
      ).toBe(false);
    });

    it('should not match URLs with different domains', () => {
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/path',
          configuredResource: 'https://example.org/path',
        }),
      ).toBe(false);
    });

    it('should not match URLs with different ports', () => {
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com:8080/path',
          configuredResource: 'https://example.com/path',
        }),
      ).toBe(false);
    });

    it('should not match URLs where one path is a sub-path of another', () => {
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/mcpxxxx',
          configuredResource: 'https://example.com/mcp',
        }),
      ).toBe(false);
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/folder',
          configuredResource: 'https://example.com/folder/subfolder',
        }),
      ).toBe(false);
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/api/v1',
          configuredResource: 'https://example.com/api',
        }),
      ).toBe(true);
    });

    it('should handle trailing slashes vs no trailing slashes', () => {
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/mcp/',
          configuredResource: 'https://example.com/mcp',
        }),
      ).toBe(true);
      expect(
        checkResourceAllowed({
          requestedResource: 'https://example.com/folder',
          configuredResource: 'https://example.com/folder/',
        }),
      ).toBe(false);
    });
  });
});

import type { Experimental_SandboxSession as SandboxSession } from '@ai-sdk/provider-utils';
import { describe, expect, it, vi } from 'vitest';
import type { HarnessV1Bootstrap } from '../../v1';
import { hashHarnessBootstrap } from './bootstrap-recipe';
import {
  createSandboxBootstrapPlan,
  normalizeSandboxWorkDir,
  resolveSessionWorkDir,
  runSandboxBootstrap,
  validateSandboxBootstrapSettings,
} from './sandbox-bootstrap';

const recipe: HarnessV1Bootstrap = {
  harnessId: 'demo',
  bootstrapDir: '/tmp/harness/demo',
  files: [{ path: '/tmp/harness/demo/a.txt', content: 'one' }],
  commands: [{ command: 'echo ok' }],
};

function makeSession(): {
  session: SandboxSession;
  run: ReturnType<typeof vi.fn>;
  readTextFile: ReturnType<typeof vi.fn>;
  writeTextFile: ReturnType<typeof vi.fn>;
} {
  const run = vi.fn(async (args: { command: string }) => {
    if (args.command === 'pwd') {
      return { exitCode: 0, stdout: '/work\n', stderr: '' };
    }
    return { exitCode: 0, stdout: '', stderr: '' };
  });
  const readTextFile = vi.fn(async () => null);
  const writeTextFile = vi.fn(async () => {});
  return {
    session: {
      description: 'mock',
      run,
      readTextFile,
      writeTextFile,
    } as unknown as SandboxSession,
    run,
    readTextFile,
    writeTextFile,
  };
}

describe('validateSandboxBootstrapSettings', () => {
  it('requires onBootstrap and bootstrapHash together', () => {
    expect(() =>
      validateSandboxBootstrapSettings({
        onBootstrap: async () => {},
      }),
    ).toThrow(/must be provided together/);

    expect(() =>
      validateSandboxBootstrapSettings({
        bootstrapHash: 'hash',
      }),
    ).toThrow(/must be provided together/);
  });

  it('rejects invalid workDir values', () => {
    for (const value of ['', '.', '/repo', '../repo', 'repo/../../x', 'a\\b']) {
      expect(() =>
        validateSandboxBootstrapSettings({
          workDir: value,
        }),
      ).toThrow(/workDir/);
    }
  });

  it('normalizes workDir values that stay inside the default cwd', () => {
    expect(normalizeSandboxWorkDir('repo/../ai-sdk')).toBe('ai-sdk');
    expect(normalizeSandboxWorkDir('./ai-sdk')).toBe('ai-sdk');
  });
});

describe('createSandboxBootstrapPlan', () => {
  it('preserves the built-in bootstrap identity when no new settings are used', async () => {
    const plan = await createSandboxBootstrapPlan({
      recipe,
      settings: {},
    });

    expect(plan.identity).toBe(await hashHarnessBootstrap(recipe));
  });

  it('changes identity when caller bootstrap hash changes', async () => {
    const a = await createSandboxBootstrapPlan({
      recipe,
      settings: {
        bootstrapHash: 'repo-v1',
        onBootstrap: async () => {},
      },
    });
    const b = await createSandboxBootstrapPlan({
      recipe,
      settings: {
        bootstrapHash: 'repo-v2',
        onBootstrap: async () => {},
      },
    });

    expect(a.identity).not.toBe(b.identity);
  });

  it('changes identity when workDir changes', async () => {
    const a = await createSandboxBootstrapPlan({
      recipe,
      settings: { workDir: 'repo-a' },
    });
    const b = await createSandboxBootstrapPlan({
      recipe,
      settings: { workDir: 'repo-b' },
    });

    expect(a.identity).not.toBe(b.identity);
  });
});

describe('resolveSessionWorkDir', () => {
  it('uses the session-scoped default path when workDir is absent', () => {
    expect(
      resolveSessionWorkDir({
        defaultWorkingDirectory: '/work',
        harnessId: 'mock',
        sessionId: 's1',
      }),
    ).toBe('/work/mock-s1');
  });

  it('uses the stable workDir when provided', () => {
    expect(
      resolveSessionWorkDir({
        defaultWorkingDirectory: '/work',
        harnessId: 'mock',
        sessionId: 's1',
        workDir: 'ai-sdk',
      }),
    ).toBe('/work/ai-sdk');
  });
});

describe('runSandboxBootstrap', () => {
  it('runs built-in bootstrap before caller bootstrap', async () => {
    const { session, run } = makeSession();
    const onSandboxBootstrap = vi.fn(async () => {});
    const recipeIdentity = await hashHarnessBootstrap(recipe);

    await runSandboxBootstrap({
      session,
      recipe,
      recipeIdentity,
      workDir: 'ai-sdk',
      onBootstrap: onSandboxBootstrap,
    });

    expect(onSandboxBootstrap).toHaveBeenCalledWith({
      session,
      workDir: '/work/ai-sdk',
      abortSignal: undefined,
    });
    expect(run.mock.calls.map(([args]) => args.command)).toEqual([
      'echo ok',
      'pwd',
      'mkdir -p "$WORK_DIR"',
    ]);
    expect(run.mock.invocationCallOrder[0]!).toBeLessThan(
      onSandboxBootstrap.mock.invocationCallOrder[0]!,
    );
  });

  it('uses the default cwd for caller bootstrap when workDir is absent', async () => {
    const { session } = makeSession();
    const onSandboxBootstrap = vi.fn(async () => {});

    await runSandboxBootstrap({
      session,
      onBootstrap: onSandboxBootstrap,
    });

    expect(onSandboxBootstrap).toHaveBeenCalledWith({
      session,
      workDir: '/work',
      abortSignal: undefined,
    });
  });
});

